using ConjuntoInteligente.PbBridge.Extensions; using ConjuntoInteligente.PbBridge.Middleware; using OpenTelemetry.Resources; using OpenTelemetry.Trace;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddPbBridge(builder.Configuration);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(c=>c.SwaggerDoc("pb-v1",new(){Title="Conjunto Inteligente · PB Bridge",Version="pb-v1",Description="Puente REST estable para clientes PowerBuilder 2022 R3."}));builder.Services.AddOpenTelemetry().ConfigureResource(r=>r.AddService("conjunto-pb-bridge")).WithTracing(t=>t.AddAspNetCoreInstrumentation().AddHttpClientInstrumentation().AddOtlpExporter(o=>{o.Endpoint=new Uri(builder.Configuration["Otel:Endpoint"]??"http://localhost:4317");}));
var app=builder.Build();if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI(c=>c.SwaggerEndpoint("/swagger/pb-v1/swagger.json","PB Bridge v1"));}app.UseMiddleware<PbGlobalExceptionMiddleware>();app.UseMiddleware<PbServiceTokenMiddleware>();app.UseAuthorization();app.MapControllers();app.MapGet("/health",()=>Results.Ok(new{status="ok",at=DateTimeOffset.UtcNow}));app.MapGet("/ready",()=>Results.Ok(new{status="ready"}));app.Run();public partial class Program;
